        /\ rw_cells bsegs m' (bv_unsigned sp + -48) [CB 8 jk; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
        /\ rw_cells bsegs m' (AINST + OI_QMUTEX) [C4 (wz 0); C4 (wz 0)]
        /\ rw_cells bsegs m' (AINST + OI_GQ) [C8 (wz (ng + nt)); C8 (wz (if ng =? 0 then ft else fg)); C8 (wz LT); C8 (wz (bg + bt))]
        /\ (ng <> 0 -> rw_cells bsegs m' LG [C8 (wz ft); C8 (wz gsz); C8 (wz gcnt)])
        /\ rw_cells bsegs m' C [C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz 0)]
        /\ rw_cells bsegs m' (AINST + OI_QMAX) [C8 (wz qmax); C8 (wz qmin); C8 (wz qcache)].
